const t = $input.first().json.body || $input.first().json;
const dir = t.direction || '?';
const asset = t.asset || '?';
const fill = t.fill_price ? Number(t.fill_price).toFixed(4) : '?';
const size = t.size_pct ? (t.size_pct * 100).toFixed(2) + '%' : '?';
const sl = t.stop_loss ? Number(t.stop_loss).toFixed(4) : '?';
const tp = t.take_profit ? Number(t.take_profit).toFixed(4) : '?';
const slip = t.slippage_pct ? (t.slippage_pct * 100).toFixed(4) + '%' : '?';
const regime = t.regime || '?';
const session = t.session || '?';
const conf = t.confidence ? (t.confidence * 100).toFixed(1) + '%' : '?';
const emoji = dir === 'BUY' ? '🟢' : '🔴';
const msg = `${emoji} **TRADE FILLED — ${dir} ${asset}**\nFill: $${fill} | Size: ${size}\nStop: $${sl} | Target: $${tp}\nSlippage: ${slip} | Confidence: ${conf}\nRegime: ${regime} | Session: ${session}`;
return [{ json: { message: msg } }];
